// VerifyChangeTool pairs the surla.verify_change identifier with its generated
// typed payload and result codecs so consumers decode tool JSON without
// restating the name-to-codec pairing fixed by the design.
func VerifyChangeTool() tools.TypedTool[*VerifyChangePayload, *VerifyChangeResult] {
	return tools.TypedTool[*VerifyChangePayload, *VerifyChangeResult]{
		Name: VerifyChange,
		Payload: tools.JSONCodec[*VerifyChangePayload]{
			ToJSON:   MarshalVerifyChangePayload,
			FromJSON: UnmarshalVerifyChangePayload,
		},
		Result: tools.JSONCodec[*VerifyChangeResult]{
			ToJSON:   MarshalVerifyChangeResult,
			FromJSON: UnmarshalVerifyChangeResult,
		},
	}
}

